import React, { useState, useEffect } from 'react';
import { useParams, Link } from 'react-router-dom';
import { ref, onValue, update } from 'firebase/database';
import { db } from '../firebase';

function SeriesDetail() {
  const { id } = useParams();
  const [series, setSeries] = useState(null);
  const [loading, setLoading] = useState(true);
  const [selectedSeason, setSelectedSeason] = useState(1);
  const [selectedUser, setSelectedUser] = useState('mucahit');
  const [watchedEpisodes, setWatchedEpisodes] = useState({
    mucahit: {},
    beyza: {}
  });

  useEffect(() => {
    const seriesRef = ref(db, `series/${id}`);
    const unsubscribe = onValue(seriesRef, (snapshot) => {
      const data = snapshot.val();
      if (data) {
        setSeries(data);
        const watchedEpisodesData = data.watchedEpisodes || {};
        setWatchedEpisodes({
          mucahit: watchedEpisodesData.mucahit || {},
          beyza: watchedEpisodesData.beyza || {}
        });
      }
      setLoading(false);
    });

    return () => unsubscribe();
  }, [id]);

  const toggleEpisodeWatched = async (season, episode) => {
    const episodeKey = `${season}-${episode}`;
    const newWatchedEpisodes = {
      ...watchedEpisodes,
      [selectedUser]: {
        ...(watchedEpisodes[selectedUser] || {}),
        [episodeKey]: !(watchedEpisodes[selectedUser] && watchedEpisodes[selectedUser][episodeKey])
      }
    };

    try {
      const seriesRef = ref(db, `series/${id}`);
      await update(seriesRef, {
        watchedEpisodes: newWatchedEpisodes
      });
      setWatchedEpisodes(newWatchedEpisodes);
    } catch (error) {
      console.error('Error updating episode status: ', error);
      alert('Bölüm durumu güncellenirken bir hata oluştu.');
    }
  };

  const toggleSeasonWatched = async (season) => {
    const episodes = Array.from({ length: series.episodesPerSeason }, (_, i) => i + 1);
    const newWatchedEpisodes = {
      ...watchedEpisodes,
      [selectedUser]: {
        ...(watchedEpisodes[selectedUser] || {})
      }
    };

    const allWatched = episodes.every(episode => 
      watchedEpisodes[selectedUser] && watchedEpisodes[selectedUser][`${season}-${episode}`]
    );

    episodes.forEach(episode => {
      newWatchedEpisodes[selectedUser][`${season}-${episode}`] = !allWatched;
    });

    try {
      const seriesRef = ref(db, `series/${id}`);
      await update(seriesRef, {
        watchedEpisodes: newWatchedEpisodes
      });
      setWatchedEpisodes(newWatchedEpisodes);
    } catch (error) {
      console.error('Error updating season status: ', error);
      alert('Sezon durumu güncellenirken bir hata oluştu.');
    }
  };

  if (loading) {
    return (
      <div className="flex justify-center items-center min-h-screen">
        <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-purple-500"></div>
      </div>
    );
  }

  if (!series) {
    return (
      <div className="flex justify-center items-center min-h-screen">
        <div className="text-center">
          <h2 className="text-2xl font-bold text-gray-700 mb-2">Dizi Bulunamadı</h2>
          <p className="text-gray-500">Aradığınız dizi bulunamadı veya silinmiş olabilir.</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-purple-50 to-pink-50 py-8 px-4">
      <div className="max-w-5xl mx-auto">
        <div className="bg-white rounded-xl shadow-lg overflow-hidden">
          {/* Dizi Başlık ve Kapak Resmi */}
          <div className="relative">
            {series.coverImage ? (
              <div className="h-64 md:h-80 w-full relative">
                <img
                  src={series.coverImage}
                  alt={series.title}
                  className="w-full h-full object-cover"
                />
                <div className="absolute inset-0 bg-gradient-to-t from-black/70 to-transparent"></div>
                <div className="absolute bottom-0 left-0 right-0 p-6">
                  <h1 className="text-3xl md:text-4xl font-bold text-white mb-2">{series.title}</h1>
                  <p className="text-white/80">
                    Sezon {series.currentSeason} • Bölüm {series.currentEpisode}
                  </p>
                </div>
              </div>
            ) : (
              <div className="h-64 md:h-80 w-full bg-gradient-to-r from-purple-500 to-pink-500 flex items-center justify-center">
                <h1 className="text-3xl md:text-4xl font-bold text-white">{series.title}</h1>
              </div>
            )}
          </div>

          {/* Düzenle Butonu */}
          <div className="absolute top-4 right-4">
            <Link
              to={`/series/${id}/edit`}
              className="bg-white/20 backdrop-blur-sm text-white py-2 px-4 rounded-lg hover:bg-white/30 transition duration-200 flex items-center"
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 mr-1" viewBox="0 0 20 20" fill="currentColor">
                <path d="M13.586 3.586a2 2 0 112.828 2.828l-.793.793-2.828-2.828.793-.793zM11.379 5.793L3 14.172V17h2.828l8.38-8.379-2.83-2.828z" />
              </svg>
              Düzenle
            </Link>
          </div>

          <div className="p-6">
            {/* Dizi Bilgileri */}
            <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-5 gap-4 mb-8">
              <div className="bg-purple-50 rounded-lg p-4 text-center">
                <p className="text-sm text-purple-600 font-medium">Toplam Sezon</p>
                <p className="text-2xl font-bold text-purple-700">{series.totalSeasons}</p>
              </div>
              <div className="bg-pink-50 rounded-lg p-4 text-center">
                <p className="text-sm text-pink-600 font-medium">Sezon Başına Bölüm</p>
                <p className="text-2xl font-bold text-pink-700">{series.episodesPerSeason}</p>
              </div>
              <div className="bg-blue-50 rounded-lg p-4 text-center">
                <p className="text-sm text-blue-600 font-medium">Mevcut Sezon</p>
                <p className="text-2xl font-bold text-blue-700">{series.currentSeason}</p>
              </div>
              <div className="bg-indigo-50 rounded-lg p-4 text-center">
                <p className="text-sm text-indigo-600 font-medium">Mevcut Bölüm</p>
                <p className="text-2xl font-bold text-indigo-700">{series.currentEpisode}</p>
              </div>
              <div className="bg-gradient-to-r from-purple-50 to-pink-50 rounded-lg p-4 text-center">
                <p className="text-sm text-purple-600 font-medium">İzleme Durumu</p>
                <p className="text-lg font-bold text-purple-700">
                  {series.watchingTogether ? 'Birlikte İzliyoruz' : 'Ayrı İzliyoruz'}
                </p>
              </div>
            </div>

            {/* Kullanıcı Seçimi */}
            <div className="mb-8">
              <h3 className="text-lg font-semibold text-gray-700 mb-3">İzleme Durumunu Güncelle</h3>
              <div className="flex justify-center space-x-4">
                <button
                  onClick={() => setSelectedUser('mucahit')}
                  className={`py-3 px-6 rounded-lg flex items-center transition-all duration-300 ${
                    selectedUser === 'mucahit'
                      ? 'bg-blue-600 text-white shadow-lg scale-105'
                      : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
                  }`}
                >
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 mr-2" viewBox="0 0 20 20" fill="currentColor">
                    <path fillRule="evenodd" d="M10 9a3 3 0 100-6 3 3 0 000 6zm-7 9a7 7 0 1114 0H3z" clipRule="evenodd" />
                  </svg>
                  Mücahit
                </button>
                <button
                  onClick={() => setSelectedUser('beyza')}
                  className={`py-3 px-6 rounded-lg flex items-center transition-all duration-300 ${
                    selectedUser === 'beyza'
                      ? 'bg-pink-600 text-white shadow-lg scale-105'
                      : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
                  }`}
                >
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 mr-2" viewBox="0 0 20 20" fill="currentColor">
                    <path fillRule="evenodd" d="M10 9a3 3 0 100-6 3 3 0 000 6zm-7 9a7 7 0 1114 0H3z" clipRule="evenodd" />
                  </svg>
                  Beyza
                </button>
              </div>
            </div>

            {/* Bölümler */}
            <div className="space-y-6">
              <h3 className="text-xl font-bold text-gray-800 flex items-center">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6 mr-2 text-purple-600" viewBox="0 0 20 20" fill="currentColor">
                  <path d="M2 6a2 2 0 012-2h6a2 2 0 012 2v8a2 2 0 01-2 2H4a2 2 0 01-2-2V6zM14.553 7.106A1 1 0 0014 8v4a1 1 0 00.553.894l2 1A1 1 0 0018 13V7a1 1 0 00-1.447-.894l-2 1z" />
                </svg>
                Bölümler
              </h3>
              
              {Array.from({ length: series.currentSeason }, (_, seasonIndex) => {
                const season = seasonIndex + 1;
                const seasonEpisodes = Array.from(
                  { length: season === series.currentSeason ? series.currentEpisode : series.episodesPerSeason },
                  (_, i) => `${season}-${i + 1}`
                );
                const isSeasonWatched = seasonEpisodes.every(ep => 
                  watchedEpisodes[selectedUser] && watchedEpisodes[selectedUser][ep]
                );
                
                return (
                  <div key={season} className="bg-white rounded-xl shadow-md overflow-hidden border border-gray-100">
                    <div className="bg-gradient-to-r from-purple-50 to-pink-50 p-4 flex justify-between items-center">
                      <h4 className="text-lg font-semibold text-gray-800 flex items-center">
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 mr-2 text-purple-600" viewBox="0 0 20 20" fill="currentColor">
                          <path fillRule="evenodd" d="M4 3a2 2 0 00-2 2v10a2 2 0 002 2h12a2 2 0 002-2V5a2 2 0 00-2-2H4zm12 12H4l4-8 3 6 2-4 3 6z" clipRule="evenodd" />
                        </svg>
                        Sezon {season}
                      </h4>
                      <button
                        onClick={() => toggleSeasonWatched(season)}
                        className={`py-1.5 px-4 rounded-lg flex items-center transition-all duration-200 ${
                          selectedUser === 'mucahit'
                            ? 'bg-blue-500 text-white hover:bg-blue-600'
                            : 'bg-pink-500 text-white hover:bg-pink-600'
                        }`}
                      >
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 mr-1" viewBox="0 0 20 20" fill="currentColor">
                          <path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd" />
                        </svg>
                        Tümünü {isSeasonWatched ? 'İzlenmedi' : 'İzlendi'} Yap
                      </button>
                    </div>
                    <div className="p-4">
                      <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-6 gap-3">
                        {Array.from(
                          { length: season === series.currentSeason ? series.currentEpisode : series.episodesPerSeason },
                          (_, episodeIndex) => {
                            const episodeKey = `${season}-${episodeIndex + 1}`;
                            const isWatched = watchedEpisodes[selectedUser] && watchedEpisodes[selectedUser][episodeKey];
                            
                            return (
                              <button
                                key={episodeIndex + 1}
                                onClick={() => toggleEpisodeWatched(season, episodeIndex + 1)}
                                className={`p-3 rounded-lg text-center transition-all duration-200 ${
                                  isWatched
                                    ? selectedUser === 'mucahit'
                                      ? 'bg-blue-500 text-white shadow-md hover:bg-blue-600'
                                      : 'bg-pink-500 text-white shadow-md hover:bg-pink-600'
                                    : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
                                }`}
                              >
                                <div className="text-sm font-medium">Bölüm</div>
                                <div className="text-lg font-bold">{episodeIndex + 1}</div>
                              </button>
                            );
                          }
                        )}
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default SeriesDetail;
